  "stuSess.refundContactNote": "Para un reembolso, contacte con <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">¿Preguntas o problemas? Contacte a <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Su reembolso ha sido iniciado a través de Stripe.</p><p class=\"text-emerald-800 mt-1\">Los reembolsos con tarjeta suelen llegar en aproximadamente <strong>5 a 10 días hábiles</strong> (los plazos bancarios pueden variar). Si no lo recibe en el plazo habitual, escriba a <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Esta clase no parece haber sido pagada a través de Tutlio Stripe (ej. transferencia bancaria o efectivo). No hay reembolso automático disponible.</p><p class=\"mt-2\">Para gestionar un reembolso, contacte con su profesor <strong>{tutor}</strong> — use el correo o los datos de sus reservas o directamente del profesor.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Esta clase no parece haber sido pagada a través de Tutlio Stripe (ej. transferencia bancaria o efectivo). No hay reembolso automático disponible.</p><p class=\"mt-2\">Como aprende a través de una organización, contacte con el <strong>administrador de la organización</strong> (a través de su profesor o los contactos publicados de la organización).</p>",
