  "orgTutorPolicy.viewBtn": "Ver normas internas",
  "orgTutorPolicy.s1Title": "1. Disposiciones generales",
  "orgTutorPolicy.s1Body": "Estas reglas regulan su uso de la plataforma Tutlio (la \"Plataforma\") como docente o profesor particular (el \"Profesor\"). La agencia educativa, escuela o centro de clases particulares que representa (la \"Organización\") le ha invitado a utilizar la Plataforma. MB Tutlio se encarga del mantenimiento y soporte técnico de la Plataforma. Al usar su cuenta, acepta estas Reglas y la Política de Privacidad.",
  "orgTutorPolicy.s2Title": "2. Gestión de cuenta y horarios",
  "orgTutorPolicy.s2Intro": "La Plataforma está diseñada para que no tenga que perder tiempo coordinando horarios de clases con los alumnos.",
  "orgTutorPolicy.s2Link": "Enlace único: Se le asigna un enlace personal de reserva de clases (según las materias que enseña) que los alumnos usan para agendar clases.",
  "orgTutorPolicy.s2Calendar": "Sincronización del calendario: Su disponibilidad depende directamente de la integración con Google Calendar (sincronización en 2 direcciones). Usted es personalmente responsable de que los horarios disponibles de su calendario sean correctos y estén actualizados. La Plataforma no permitirá que los alumnos reserven horarios marcados como ocupados en su calendario.",
  "orgTutorPolicy.s2Security": "Seguridad de la cuenta: Su cuenta es personal. Debe mantener sus credenciales de acceso seguras y no compartirlas con terceros.",
  "orgTutorPolicy.s3Title": "3. Cancelaciones de clases y lista de espera",
  "orgTutorPolicy.s3Intro": "La Plataforma ayuda a optimizar su horario y evitar huecos vacíos:",
  "orgTutorPolicy.s3Auto": "Si un alumno cancela una clase, la Plataforma envía automáticamente una notificación (SMS/correo) a otros alumnos en su lista de espera, ofreciendo el horario liberado. No se requiere ninguna acción adicional por su parte.",
  "orgTutorPolicy.s3Rules": "Las reglas de cancelación de clases (con cuánta antelación se puede cancelar, consecuencias) las establece su Organización.",
  "orgTutorPolicy.s4Title": "4. Finanzas y pagos",
  "orgTutorPolicy.s4Intro": "No necesita preocuparse por facturar ni cobrar pagos a los padres:",
  "orgTutorPolicy.s4Advance": "Todos los pagos de los alumnos (o padres) por sus clases se cobran por adelantado a través de la Plataforma y se transfieren directamente a su Organización.",
  "orgTutorPolicy.s4Confirmed": "Usted imparte una clase solo cuando está confirmada en el sistema (lo que significa que el cobro ya se ha realizado).",
  "orgTutorPolicy.s4Contact": "Para su salario, calendario de pagos y otros asuntos financieros, contacte directamente al administrador de su Organización. MB Tutlio no realiza transacciones financieras directas con los Profesores.",
  "orgTutorPolicy.s5Title": "5. Protección de datos de alumnos (RGPD)",
  "orgTutorPolicy.s5Intro": "Como Profesor, tiene acceso a los datos personales de los alumnos, notas internas y materiales de aprendizaje. Se compromete a:",
  "orgTutorPolicy.s5Use": "Utilizar estos datos exclusivamente para la organización e impartición de clases.",
  "orgTutorPolicy.s5NoCopy": "No copiar, exportar ni distribuir la información de contacto de alumnos o padres fuera de la Plataforma.",
  "orgTutorPolicy.s5Notes": "Proteger los registros internos de la Organización (notas sobre el progreso del alumno), visibles solo para usted y la administración de la Organización, no para alumnos ni padres.",
  "orgTutorPolicy.s5Termination": "Al finalizar su relación laboral con la Organización, su acceso a estos datos será revocado de forma inmediata.",
  "orgTutorPolicy.s6Title": "6. Funcionamiento técnico y limitación de responsabilidad",
  "orgTutorPolicy.s6Body": "Está prohibido utilizar la Plataforma con fines ilícitos, distribuir enlaces maliciosos en materiales de clase o interferir de cualquier otra forma con el sistema. MB Tutlio garantiza el funcionamiento y mantenimiento técnico de la Plataforma, pero no asume responsabilidad por interrupciones causadas por su conexión a internet, fallos de dispositivos o una configuración incorrecta de Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Soporte y contacto",
  "orgTutorPolicy.s7Org": "Para consultas sobre horarios de clases, salarios, asignación de alumnos u organización del trabajo, contacte al administrador de su Organización.",
  "orgTutorPolicy.s7Tech": "Ante errores técnicos de la Plataforma (la sincronización del calendario no funciona, no recibe notificaciones), informe al administrador de su Organización, quien contactará al equipo de soporte técnico de Tutlio.",
  "register.orgPolicyConsent": "Al usar la plataforma, aceptas las",
  "register.orgPolicyLink": "normas internas",
