  "quiz.intro.solo.title": "Su tiempo es más valioso en clase que en tareas administrativas",
  "quiz.intro.solo.body": "Dar clases particulares por cuenta propia puede parecer sencillo, pero cada alumno implica horarios, pagos, notas, recordatorios y mensajes.",
  "quiz.intro.solo.visualAlt": "Profesor independiente dando clase mientras Tutlio conecta las tareas relacionadas con la lección",
